const body = $('Callback Webhook').first().json.body || {};
const cfg = $('Config').first().json;
if (!body.task_id) throw new Error('Missing task_id in callback payload');
if (body.tracker && body.tracker !== 'trello') throw new Error('This workflow handles trello cards only, got: ' + body.tracker);

const lines = [];
let target;
if (body.status === 'success') {
  target = cfg.review_list_id;
  lines.push('✅ أنهى Claude التطوير واجتاز الاختبارات والمراجعة، وفتح Pull Request لمراجعتك.');
  lines.push(`PR: ${body.pr_url}`);
} else if (body.status === 'blocked') {
  target = cfg.needs_attention_list_id;
  lines.push('⏸️ يحتاج Claude توضيحًا قبل التنفيذ. أجب على الأسئلة في وصف البطاقة ثم أعدها إلى قائمة Ready for Claude.');
} else {
  target = cfg.needs_attention_list_id;
  lines.push('❌ لم يتمكن Claude من إكمال المهمة.');
  if (body.reason) lines.push(`السبب: ${body.reason}`);
}
if (body.summary) lines.push('', 'الملخص:', body.summary);
if (Array.isArray(body.questions) && body.questions.length) {
  lines.push('', 'أسئلة:', ...body.questions.map(q => `• ${q}`));
}
if (body.tests_gate) lines.push('', `بوابة الاختبارات: ${body.tests_gate}`);
if (body.run_url) lines.push(`سجل التشغيل: ${body.run_url}`);

return [{ json: { task_id: String(body.task_id), target_list: target, comment: lines.join('\n') } }];
